def rotate_quat(axis, angle, orientation):
    scale = sin(angle / 2.0)
    return multiply_quat(
        [axis[0] * scale, axis[1] * scale, axis[2] * scale,
         cos(angle / 2.0)],
        orientation,
    )

servo.code:
def servo(sdk, state, target, orientation, grip, speed=0.8):
    current = state["eef_quat"]
    inverse = [-current[0], -current[1], -current[2], current[3]]
    error = multiply_quat(orientation, inverse)
    sign = 1.0 if error[3] >= 0.0 else -1.0
    translation = [
        clamp(35.0 * (target[i] - state["eef_pos"][i]), -speed, speed)
        for i in range(3)
    ]
    rotation = [
        clamp(8.0 * sign * error[i], -0.8, 0.8)
        for i in range(3)
    ]
    sdk.step_raw(translation + rotation + [grip], steps=1)
    return sdk.get_state()

